indow closes.\n32|\t// This should be called near the end of a main() function as it will block.\n33|\tRun()\n34|\n35|\t// Calling Quit on the application will cause the application to exit\n36|\t// cleanly, closing all open windows.\n37|\t// This function does no thing on a mobile device as the application lifecycle is\n38|\t// managed by the operating system.\n39|\tQuit()\n40|\n41|\t// Driver returns the driver that is rendering this application.\n42|\t// Typically not needed for day to day work, mostly internal functionality.\n43|\tDriver() Driver\n44|\n45|\t// UniqueID returns the application unique identifier, if set.\n46|\t// This must be set for use of the Preferences() functions... see NewWithId(string)\n47|\tUniqueID() string\n48|\n49|\t// SendNotification sends a system notification that will be displayed in the operating system's notification area.\n50|\tSendNotification(*Notification)\n51|\n52|\t// Settings return the globally set settings, determining theme and so on.\n53|\tSettings() Settings\n54|\n55|\t// Preferences returns the application preferences, used for storing configuration and state\n56|\tPreferences() Preferences\n57|\n58|\t// Storage returns a storage handler specific to this application.\n59|\tStorage() Storage\n60|\n61|\t// Lifecycle returns a type that allows apps to hook in to lifecycle events.\n62|\tLifecycle() Lifecycle\n63|}\n64|\n65|var app App\n66|var appLock sync.RWMutex\n67|\n68|// SetCurrentApp is an internal function to set the app instance currently running.\n69|func SetCurrentApp(current App) {\n70|\tappLock.Lock()\n71|\tdefer appLock.Unlock()\n72|\n73|\tapp = current\n74|}\n75|\n76|// CurrentApp returns the current application, for which there is only 1 per process.\n77|func CurrentApp() App {\n78|\tappLock.RLock()\n79|\tdefer appLock.RUnlock()\n80|\n81|\tif app == nil {\n82|\t\tLogError(\"Attempt to access current Fyne app when none is started\", nil)\n83|\t}\n84|\treturn app\n85|}\n86|\n87|// Lifecycle represents the various phases that an app can transition through.\n88|//\n89|// Since: 2.1\n90|type Lifecycle interface {\n91|\t// SetOnEnteredForeground hooks into the app becoming foreground and gaining focus.\n92|\tSetOnEnteredForeground(func())\n93|\t// SetOnExitedForeground hooks into the app losing input focus and going into the background.\n94|\tSetOnExitedForeground(func())\n95|\t// SetOnStarted hooks into an event that says the app is now running.\n96|\tSetOnStarted(func())\n97|\t// SetOnStopped hooks into an event that says the app is no longer running.\n98|\tSetOnStopped(func())\n99|}"}], "task_turn": 3, "text": "<summary>Found Fyne toolkit structure. Now reading key files to understand existing interfaces before implementing the 7 targets.</summary>", "synopsis": "Found Fyne toolkit structure. Now reading key files to understand existing interfaces before implementing the 7 targets.", "archive_sequence": 6, "archived_at": 1790739010.3564465}
