package fyne

import (
	"net/url"
	"sync"
)

// AppMetadata captures an application's build-time metadata including its
// unique identifier, display name, version information, and bundled icon.
//
// Since: 2.2
type AppMetadata struct {
	// ID is the unique application identifier, such as "com.example.myapp"
	ID string
	// Name is the human-friendly application name for display purposes
	Name string
	// Version is the application version string, typically semantic versioning
	Version string
	// Build is the application build number
	Build int
	// Icon is the application icon resource bundled at build time
	Icon Resource
}

// An App is the definition of a graphical application.
// Apps can have multiple windows, by default they will exit when all windows
// have been closed. This can be modified using SetMaster() or SetCloseIntercept().
// To start an application you need to call Run() somewhere in your main() function.
// Alternatively use the window.ShowAndRun() function for your main window.
type App interface {

