// Package desktop provides desktop-specific driver capabilities
package desktop

import "fyne.io/fyne/v2"

// App defines a desktop application with system tray support.
// This extends the standard fyne.App interface with desktop-specific features.
//
// Since: 2.2
type App interface {
	fyne.App

	// SetSystemTrayMenu sets the menu that will be displayed when the system tray icon is right clicked.
	// When set to nil the system tray item will be removed.
	//
	// The system tray menu is a desktop-specific feature and will only work on
	// Windows, macOS, and Linux desktop environments that support system tray icons.
	SetSystemTrayMenu(menu *fyne.Menu)
}

